import React, { useEffect, useState } from 'react';
import api from '../../services/api';

function AdminHouses() {
  const [houses, setHouses] = useState([]);

  useEffect(() => {
    const fetchHouses = async () => {
      try {
        const res = await api.get('/houses');
        setHouses(res.data.houses || []);
      } catch {
        setHouses([]);
      }
    };
    fetchHouses();
  }, []);

  return (
    <div>
      <h4>Listado de Casas</h4>
      <ul className="list-group">
        {houses.map((house) => (
          <li key={house.id} className="list-group-item d-flex justify-content-between align-items-center">
            <span>
              {house.name} – {house.location}
            </span>
            <span className="badge bg-secondary">{house.availability ? 'Activa' : 'Inactiva'}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default AdminHouses;
